	args := &SecretGrantRevokeArgs{
		RelationKey: &c.relation,
	}
	if c.unit != "" {
		args.UnitName = &c.unit
	}
	if c.app != "" {
		args.ApplicationName = &c.app
	}

	return c.ctx.GrantSecret(c.secretURI, args)
}

